const cred = await navigator.credentials.get({
  publicKey: {
    challenge: base64urlDecode(serverChallenge),   // random, single-use
    rpId: 'acme.com',
    userVerification: 'required',
    allowCredentials: []                            // discoverable passkeys
  }
});
